/* cpp-L4.js — CPP Lesson 4 content (EN + TR) */
var CPP_L4 = {
en: "<p class=\"l-text\">Templates are C++'s mechanism for <strong>generic programming</strong> — writing code that works with any type. The problem they solve is simple: without templates, you would need to write separate versions of the same function for every type. Need a <code>max</code> function? Write one for <code>int</code>, one for <code>double</code>, one for <code>string</code>... Templates let you write it once.</p><div class=\"lesson-outcomes\" style=\"background:rgba(200,169,110,0.06);border-left:3px solid #c8a96e;padding:1rem 1.2rem;margin:1.5rem 0;border-radius:0 8px 8px 0\"><div style=\"font-size:0.78rem;font-weight:700;letter-spacing:0.08em;color:#c8a96e;margin-bottom:0.6rem\">📍 WHAT YOU'LL LEARN</div><ul style=\"margin:0;padding-left:1.3rem;line-height:1.65;font-size:0.93rem;color:rgba(235,230,220,0.92)\"><li>Define function and class templates that work with any compatible type</li><li>Specialize templates for performance-critical types when needed</li><li>Use template parameter packs and variadic templates for flexible APIs</li><li>Apply concepts (C++20) to constrain template parameters with clear errors</li><li>Build a generic Stack or Queue data structure with templates</li></ul></div><div class=\"l-highlight\"><strong>The DRY problem without templates:</strong> Imagine writing <code>int max_int(int a, int b)</code>, <code>double max_double(double a, double b)</code>, <code>string max_string(string a, string b)</code> — all with identical logic. Now imagine a bug fix: you have to update all three. Templates eliminate this duplication entirely.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> templates.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"cm\">// Function template: works with ANY type that supports &gt;</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n<span class=\"ty\">T</span> <span class=\"fn\">max_val</span>(<span class=\"ty\">T</span> a, <span class=\"ty\">T</span> b) {\n    <span class=\"kw\">return</span> (a &gt; b) ? a : b;\n}\n\n<span class=\"cm\">// Template with multiple type parameters</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>, <span class=\"kw\">typename</span> <span class=\"ty\">U</span>&gt;\n<span class=\"ty\">void</span> <span class=\"fn\">print_pair</span>(<span class=\"kw\">const</span> <span class=\"ty\">T</span>&amp; first, <span class=\"kw\">const</span> <span class=\"ty\">U</span>&amp; second) {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"(\"</span> &lt;&lt; first &lt;&lt; <span class=\"str\">\", \"</span> &lt;&lt; second &lt;&lt; <span class=\"str\">\")\\n\"</span>;\n}\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"cm\">// Compiler generates int, double, string versions automatically</span>\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"max(3, 7) = \"</span> &lt;&lt; <span class=\"fn\">max_val</span>(<span class=\"num\">3</span>, <span class=\"num\">7</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"max(3.14, 2.72) = \"</span> &lt;&lt; <span class=\"fn\">max_val</span>(<span class=\"num\">3.14</span>, <span class=\"num\">2.72</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"max(\\\"apple\\\", \\\"banana\\\") = \"</span>\n              &lt;&lt; <span class=\"fn\">max_val</span>(<span class=\"ty\">std::string</span>(<span class=\"str\">\"apple\"</span>), <span class=\"ty\">std::string</span>(<span class=\"str\">\"banana\"</span>)) &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"fn\">print_pair</span>(<span class=\"str\">\"age\"</span>, <span class=\"num\">25</span>);\n    <span class=\"fn\">print_pair</span>(<span class=\"num\">3.14</span>, <span class=\"str\">\"pi\"</span>);\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>max(3, 7) = 7\nmax(3.14, 2.72) = 3.14\nmax(\"apple\", \"banana\") = banana\n(age, 25)\n(3.14, pi)</code></pre></div></div><p class=\"l-text\"><strong>How template instantiation works:</strong> Templates are not compiled into code until they are actually used. When you call <code>max_val(3, 7)</code>, the compiler sees <code>T = int</code> and generates a concrete <code>int max_val(int, int)</code> function. This is called <strong>instantiation</strong>. The compiler literally creates a new copy of the function for each type you use. This is why templates are typically defined in header files — the compiler needs to see the full definition to instantiate.</p><p class=\"l-text\"><strong>Class templates</strong> — you can also template entire classes. Let's build a simple Stack:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> stack_template.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;vector&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;stdexcept&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n<span class=\"kw\">class</span> <span class=\"ty\">Stack</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"ty\">std::vector</span>&lt;<span class=\"ty\">T</span>&gt; data_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">void</span> <span class=\"fn\">push</span>(<span class=\"kw\">const</span> <span class=\"ty\">T</span>&amp; val) { data_.<span class=\"fn\">push_back</span>(val); }\n\n    <span class=\"ty\">T</span> <span class=\"fn\">pop</span>() {\n        <span class=\"kw\">if</span> (data_.<span class=\"fn\">empty</span>()) <span class=\"kw\">throw</span> <span class=\"ty\">std::runtime_error</span>(<span class=\"str\">\"Stack underflow\"</span>);\n        <span class=\"ty\">T</span> val = data_.<span class=\"fn\">back</span>();\n        data_.<span class=\"fn\">pop_back</span>();\n        <span class=\"kw\">return</span> val;\n    }\n\n    <span class=\"kw\">const</span> <span class=\"ty\">T</span>&amp; <span class=\"fn\">top</span>() <span class=\"kw\">const</span> {\n        <span class=\"kw\">if</span> (data_.<span class=\"fn\">empty</span>()) <span class=\"kw\">throw</span> <span class=\"ty\">std::runtime_error</span>(<span class=\"str\">\"Stack empty\"</span>);\n        <span class=\"kw\">return</span> data_.<span class=\"fn\">back</span>();\n    }\n\n    <span class=\"ty\">bool</span> <span class=\"fn\">empty</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> data_.<span class=\"fn\">empty</span>(); }\n    <span class=\"ty\">size_t</span> <span class=\"fn\">size</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> data_.<span class=\"fn\">size</span>(); }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"ty\">Stack</span>&lt;<span class=\"ty\">int</span>&gt; nums;\n    nums.<span class=\"fn\">push</span>(<span class=\"num\">10</span>);\n    nums.<span class=\"fn\">push</span>(<span class=\"num\">20</span>);\n    nums.<span class=\"fn\">push</span>(<span class=\"num\">30</span>);\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Int stack: \"</span>;\n    <span class=\"kw\">while</span> (!nums.<span class=\"fn\">empty</span>()) {\n        <span class=\"fn\">std::cout</span> &lt;&lt; nums.<span class=\"fn\">pop</span>() &lt;&lt; <span class=\"str\">\" \"</span>;\n    }\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"ty\">Stack</span>&lt;<span class=\"ty\">std::string</span>&gt; words;\n    words.<span class=\"fn\">push</span>(<span class=\"str\">\"Hello\"</span>);\n    words.<span class=\"fn\">push</span>(<span class=\"str\">\"World\"</span>);\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"String stack top: \"</span> &lt;&lt; words.<span class=\"fn\">top</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Int stack: 30 20 10\nString stack top: World</code></pre></div></div><p class=\"l-text\"><strong>STL Containers</strong> — The Standard Template Library provides production-quality containers. Choosing the right one matters for performance:</p><ul class=\"l-list\"><li><strong><code>vector</code></strong> — dynamic array. Your default container. O(1) random access, O(1) amortized push_back. Use unless you have a specific reason not to.</li><li><strong><code>list</code></strong> — doubly-linked list. O(1) insert/remove anywhere (if you have an iterator), but O(n) random access and poor cache locality.</li><li><strong><code>map</code></strong> — ordered key-value pairs (red-black tree). O(log n) lookup/insert. Keys stay sorted.</li><li><strong><code>unordered_map</code></strong> — hash table. O(1) average lookup/insert. Faster than map for most use cases, but no ordering.</li><li><strong><code>set</code></strong> — ordered unique elements. Like map without values.</li><li><strong><code>stack</code> / <code>queue</code></strong> — LIFO/FIFO adapters. Restricted interfaces on top of deque.</li></ul><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> stl_containers.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;vector&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;map&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;set&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;algorithm&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;numeric&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"cm\">// === VECTOR ===</span>\n    <span class=\"ty\">std::vector</span>&lt;<span class=\"ty\">int</span>&gt; nums = {<span class=\"num\">5</span>, <span class=\"num\">2</span>, <span class=\"num\">8</span>, <span class=\"num\">1</span>, <span class=\"num\">9</span>, <span class=\"num\">3</span>};\n    <span class=\"fn\">std::sort</span>(nums.<span class=\"fn\">begin</span>(), nums.<span class=\"fn\">end</span>());\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Sorted: \"</span>;\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> n : nums) <span class=\"fn\">std::cout</span> &lt;&lt; n &lt;&lt; <span class=\"str\">\" \"</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"ty\">int</span> sum = <span class=\"fn\">std::accumulate</span>(nums.<span class=\"fn\">begin</span>(), nums.<span class=\"fn\">end</span>(), <span class=\"num\">0</span>);\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Sum: \"</span> &lt;&lt; sum &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"kw\">auto</span> it = <span class=\"fn\">std::find</span>(nums.<span class=\"fn\">begin</span>(), nums.<span class=\"fn\">end</span>(), <span class=\"num\">8</span>);\n    <span class=\"kw\">if</span> (it != nums.<span class=\"fn\">end</span>()) {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Found 8 at index \"</span> &lt;&lt; (it - nums.<span class=\"fn\">begin</span>()) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"cm\">// === MAP ===</span>\n    <span class=\"ty\">std::map</span>&lt;<span class=\"ty\">std::string</span>, <span class=\"ty\">int</span>&gt; ages;\n    ages[<span class=\"str\">\"Begüm\"</span>] = <span class=\"num\">30</span>;\n    ages[<span class=\"str\">\"Mikail\"</span>] = <span class=\"num\">25</span>;\n    ages[<span class=\"str\">\"Defne\"</span>] = <span class=\"num\">35</span>;\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"\\nMap (sorted by key):\\n\"</span>;\n    <span class=\"kw\">for</span> (<span class=\"kw\">const</span> <span class=\"kw\">auto</span>&amp; [name, age] : ages) {  <span class=\"cm\">// structured binding (C++17)</span>\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  \"</span> &lt;&lt; name &lt;&lt; <span class=\"str\">\": \"</span> &lt;&lt; age &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"cm\">// === SET ===</span>\n    <span class=\"ty\">std::set</span>&lt;<span class=\"ty\">int</span>&gt; unique = {<span class=\"num\">3</span>, <span class=\"num\">1</span>, <span class=\"num\">4</span>, <span class=\"num\">1</span>, <span class=\"num\">5</span>, <span class=\"num\">9</span>, <span class=\"num\">2</span>, <span class=\"num\">6</span>, <span class=\"num\">5</span>};\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"\\nSet (unique, sorted): \"</span>;\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> n : unique) <span class=\"fn\">std::cout</span> &lt;&lt; n &lt;&lt; <span class=\"str\">\" \"</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Sorted: 1 2 3 5 8 9\nSum: 28\nFound 8 at index 4\n\nMap (sorted by key):\n  Begüm: 30\n  Mikail: 25\n  Defne: 35\n\nSet (unique, sorted): 1 2 3 4 5 6 9</code></pre></div></div><p class=\"l-text\"><strong>STL Algorithms</strong> — The <code>&lt;algorithm&gt;</code> header provides dozens of ready-to-use algorithms that work with any container through iterators: <code>sort</code>, <code>find</code>, <code>count</code>, <code>transform</code>, <code>accumulate</code>, <code>remove_if</code>, <code>any_of</code>, <code>all_of</code>, and many more. They separate the \"what to do\" from \"what container to do it on\" — the same <code>sort</code> works on vectors, arrays, and deques.</p><div class=\"l-note\"><strong>Tip:</strong> When choosing a container, default to <code>std::vector</code>. It has the best cache performance (contiguous memory), and for small collections (up to a few hundred elements), a sorted vector with binary search is often faster than a <code>map</code> due to cache locality.</div><h3 class=\"l-h3\" style=\"margin-top:2.2rem\">Template Specialization — Full &amp; Partial</h3><p class=\"l-text\">Sometimes the generic template is <em>almost</em> right, but one specific type needs special handling — maybe for performance, maybe because the generic algorithm simply does not apply. <strong>Template specialization</strong> lets you provide a custom implementation for a specific type (full specialization) or for a whole family of types like \"all pointers\" (partial specialization). The classic real-world example is <code>std::vector&lt;bool&gt;</code>, which is specialized to pack 8 booleans per byte instead of storing one byte each.</p><div class=\"calc-cards\"><div class=\"calc-card\"><div class=\"cc-title\">Full Specialization</div><div class=\"cc-body\">Replace the whole template for one exact type: <code>template&lt;&gt; class MyClass&lt;int&gt; { ... };</code>. Used when one type needs a completely different implementation.</div></div><div class=\"calc-card\"><div class=\"cc-title\">Partial Specialization</div><div class=\"cc-body\">Constrain the template to a family of types — only for class templates: <code>template&lt;typename T&gt; class MyClass&lt;T*&gt; { ... };</code>. The example above matches every pointer type.</div></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> specialization.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"cm\">// Primary template — works for any T</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n<span class=\"kw\">struct</span> <span class=\"ty\">TypeInfo</span> {\n    <span class=\"kw\">static</span> <span class=\"ty\">std::string</span> <span class=\"fn\">name</span>() { <span class=\"kw\">return</span> <span class=\"str\">\"unknown\"</span>; }\n    <span class=\"kw\">static</span> <span class=\"kw\">constexpr</span> <span class=\"ty\">bool</span> is_pointer = <span class=\"kw\">false</span>;\n};\n\n<span class=\"cm\">// Full specialization for int</span>\n<span class=\"kw\">template</span>&lt;&gt;\n<span class=\"kw\">struct</span> <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">int</span>&gt; {\n    <span class=\"kw\">static</span> <span class=\"ty\">std::string</span> <span class=\"fn\">name</span>() { <span class=\"kw\">return</span> <span class=\"str\">\"int\"</span>; }\n    <span class=\"kw\">static</span> <span class=\"kw\">constexpr</span> <span class=\"ty\">bool</span> is_pointer = <span class=\"kw\">false</span>;\n};\n\n<span class=\"cm\">// Full specialization for double</span>\n<span class=\"kw\">template</span>&lt;&gt;\n<span class=\"kw\">struct</span> <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">double</span>&gt; {\n    <span class=\"kw\">static</span> <span class=\"ty\">std::string</span> <span class=\"fn\">name</span>() { <span class=\"kw\">return</span> <span class=\"str\">\"double\"</span>; }\n    <span class=\"kw\">static</span> <span class=\"kw\">constexpr</span> <span class=\"ty\">bool</span> is_pointer = <span class=\"kw\">false</span>;\n};\n\n<span class=\"cm\">// PARTIAL specialization: any pointer type T*</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n<span class=\"kw\">struct</span> <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">T</span>*&gt; {\n    <span class=\"kw\">static</span> <span class=\"ty\">std::string</span> <span class=\"fn\">name</span>() { <span class=\"kw\">return</span> <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">T</span>&gt;::<span class=\"fn\">name</span>() + <span class=\"str\">\"*\"</span>; }\n    <span class=\"kw\">static</span> <span class=\"kw\">constexpr</span> <span class=\"ty\">bool</span> is_pointer = <span class=\"kw\">true</span>;\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">int</span>&gt;::<span class=\"fn\">name</span>()       &lt;&lt; <span class=\"str\">\" ptr=\"</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">int</span>&gt;::is_pointer       &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">double</span>&gt;::<span class=\"fn\">name</span>()    &lt;&lt; <span class=\"str\">\" ptr=\"</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">double</span>&gt;::is_pointer    &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">int</span>*&gt;::<span class=\"fn\">name</span>()      &lt;&lt; <span class=\"str\">\" ptr=\"</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">int</span>*&gt;::is_pointer      &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">double</span>*&gt;::<span class=\"fn\">name</span>()   &lt;&lt; <span class=\"str\">\" ptr=\"</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">double</span>*&gt;::is_pointer   &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">char</span>&gt;::<span class=\"fn\">name</span>()      &lt;&lt; <span class=\"str\">'\\n'</span>;  <span class=\"cm\">// falls back to primary</span>\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>int ptr=0\ndouble ptr=0\nint* ptr=1\ndouble* ptr=1\nunknown</code></pre></div></div><p class=\"l-text\">Notice how <code>TypeInfo&lt;char&gt;</code> falls back to the <em>primary</em> template (\"unknown\") because no specialization matches. The compiler picks the most specific match available — exact specializations first, then partial, then primary. This is exactly how the standard library implements traits like <code>std::is_pointer</code> and <code>std::remove_pointer</code>.</p><h3 class=\"l-h3\" style=\"margin-top:2.2rem\">Variadic Templates &amp; Parameter Packs</h3><p class=\"l-text\">Before C++11, templates accepted a fixed number of type parameters. <strong>Variadic templates</strong> changed that: a single template can now accept any number of arguments of any types. The syntax <code>template&lt;typename... Args&gt;</code> declares a <em>parameter pack</em> — <code>Args</code> is not one type, it is a list of types. You expand the pack with <code>Args...</code> in function signatures and <code>args...</code> in call expressions. This is how <code>std::tuple</code>, <code>std::make_shared</code>, <code>std::vector::emplace_back</code>, and <code>printf</code>-style type-safe formatters are built.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> variadic.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"cm\">// --- Style 1: recursive variadic (pre-C++17) ---</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n<span class=\"ty\">T</span> <span class=\"fn\">sum_rec</span>(<span class=\"ty\">T</span> v) { <span class=\"kw\">return</span> v; }                <span class=\"cm\">// base case</span>\n\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>, <span class=\"kw\">typename</span>... <span class=\"ty\">Rest</span>&gt;\n<span class=\"ty\">T</span> <span class=\"fn\">sum_rec</span>(<span class=\"ty\">T</span> first, <span class=\"ty\">Rest</span>... rest) {\n    <span class=\"kw\">return</span> first + <span class=\"fn\">sum_rec</span>(rest...);     <span class=\"cm\">// peel one, recurse</span>\n}\n\n<span class=\"cm\">// --- Style 2: fold expression (C++17, simpler!) ---</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span>... <span class=\"ty\">Args</span>&gt;\n<span class=\"kw\">auto</span> <span class=\"fn\">sum_fold</span>(<span class=\"ty\">Args</span>... args) {\n    <span class=\"kw\">return</span> (args + ...);                  <span class=\"cm\">// unary right fold: a1+(a2+(a3+a4))</span>\n}\n\n<span class=\"cm\">// Variadic print using a fold over the comma operator</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span>... <span class=\"ty\">Args</span>&gt;\n<span class=\"ty\">void</span> <span class=\"fn\">print_all</span>(<span class=\"kw\">const</span> <span class=\"ty\">Args</span>&amp;... args) {\n    ((<span class=\"fn\">std::cout</span> &lt;&lt; args &lt;&lt; <span class=\"str\">\" \"</span>), ...);\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n}\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"sum_rec(1,2,3,4,5)  = \"</span> &lt;&lt; <span class=\"fn\">sum_rec</span>(<span class=\"num\">1</span>,<span class=\"num\">2</span>,<span class=\"num\">3</span>,<span class=\"num\">4</span>,<span class=\"num\">5</span>)  &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"sum_fold(1,2,3,4,5) = \"</span> &lt;&lt; <span class=\"fn\">sum_fold</span>(<span class=\"num\">1</span>,<span class=\"num\">2</span>,<span class=\"num\">3</span>,<span class=\"num\">4</span>,<span class=\"num\">5</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"sum_fold(1.5, 2.5)  = \"</span> &lt;&lt; <span class=\"fn\">sum_fold</span>(<span class=\"num\">1.5</span>, <span class=\"num\">2.5</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"fn\">print_all</span>(<span class=\"str\">\"id=\"</span>, <span class=\"num\">42</span>, <span class=\"str\">\"name=\"</span>, <span class=\"ty\">std::string</span>(<span class=\"str\">\"Mikail\"</span>), <span class=\"str\">\"pi=\"</span>, <span class=\"num\">3.14</span>);\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>sum_rec(1,2,3,4,5)  = 15\nsum_fold(1,2,3,4,5) = 15\nsum_fold(1.5, 2.5)  = 4\nid= 42 name= Mikail pi= 3.14</code></pre></div></div><div class=\"l-highlight\"><strong>Fold expression cheat sheet (C++17):</strong> <code>(pack op ...)</code> is a unary right fold, <code>(... op pack)</code> is a unary left fold, <code>(pack op ... op init)</code> is a binary right fold with an initial value. Useful operators: <code>+</code>, <code>*</code>, <code>&amp;&amp;</code>, <code>||</code>, and the comma operator <code>,</code> for side-effect loops over a pack.</div><p class=\"l-text\"><strong>Where the standard library uses this:</strong> <code>std::make_shared&lt;T&gt;(args...)</code> forwards any constructor arguments to <code>T</code> with a parameter pack and <code>std::forward&lt;Args&gt;(args)...</code> (perfect forwarding). <code>std::tuple&lt;Ts...&gt;</code> stores a heterogeneous list. <code>std::vector::emplace_back(args...)</code> constructs an element in place from a forwarded pack — zero copies, zero moves.</p><h3 class=\"l-h3\" style=\"margin-top:2.2rem\">C++20 Concepts — Constraints That Read Like English</h3><p class=\"l-text\">Before C++20, the only way to constrain a template was <strong>SFINAE</strong> (Substitution Failure Is Not An Error), which produced 200-line error messages full of <code>std::enable_if&lt;std::is_integral_v&lt;T&gt; &amp;&amp; ...&gt;::type</code>. <strong>Concepts</strong> replace that with named, readable constraints. A concept is a compile-time predicate over types; a <code>requires</code> clause attaches it to a template.</p><div class=\"calc-cards\"><div class=\"calc-card\"><div class=\"cc-title\">Old SFINAE</div><div class=\"cc-body\"><code>template&lt;typename T, std::enable_if_t&lt;std::is_integral_v&lt;T&gt;, int&gt; = 0&gt;</code> — works, but errors are a wall of text and intent is hidden.</div></div><div class=\"calc-card\"><div class=\"cc-title\">New Concepts</div><div class=\"cc-body\"><code>template&lt;std::integral T&gt;</code> or <code>template&lt;typename T&gt; requires std::integral&lt;T&gt;</code> — same constraint, one line, errors say \"T does not satisfy integral\".</div></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> concepts.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;concepts&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;vector&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"cm\">// Define your own concept: \"a type that supports a + b\"</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n<span class=\"kw\">concept</span> <span class=\"ty\">Addable</span> = <span class=\"kw\">requires</span>(<span class=\"ty\">T</span> a, <span class=\"ty\">T</span> b) {\n    { a + b } -&gt; <span class=\"ty\">std::convertible_to</span>&lt;<span class=\"ty\">T</span>&gt;;\n};\n\n<span class=\"cm\">// Use the concept directly in the template parameter</span>\n<span class=\"kw\">template</span>&lt;<span class=\"ty\">Addable</span> <span class=\"ty\">T</span>&gt;\n<span class=\"ty\">T</span> <span class=\"fn\">add</span>(<span class=\"ty\">T</span> a, <span class=\"ty\">T</span> b) { <span class=\"kw\">return</span> a + b; }\n\n<span class=\"cm\">// Use a standard concept with a requires clause</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n    <span class=\"kw\">requires</span> <span class=\"ty\">std::integral</span>&lt;<span class=\"ty\">T</span>&gt;\n<span class=\"ty\">T</span> <span class=\"fn\">only_ints</span>(<span class=\"ty\">T</span> x) { <span class=\"kw\">return</span> x * <span class=\"num\">2</span>; }\n\n<span class=\"cm\">// A more interesting concept: a Container has begin(), end(), and a size_type</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">C</span>&gt;\n<span class=\"kw\">concept</span> <span class=\"ty\">Container</span> = <span class=\"kw\">requires</span>(<span class=\"ty\">C</span> c) {\n    c.<span class=\"fn\">begin</span>();\n    c.<span class=\"fn\">end</span>();\n    <span class=\"kw\">typename</span> <span class=\"ty\">C</span>::value_type;\n};\n\n<span class=\"kw\">template</span>&lt;<span class=\"ty\">Container</span> <span class=\"ty\">C</span>&gt;\n<span class=\"ty\">void</span> <span class=\"fn\">print_container</span>(<span class=\"kw\">const</span> <span class=\"ty\">C</span>&amp; c) {\n    <span class=\"kw\">for</span> (<span class=\"kw\">const</span> <span class=\"kw\">auto</span>&amp; x : c) <span class=\"fn\">std::cout</span> &lt;&lt; x &lt;&lt; <span class=\"str\">\" \"</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n}\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"fn\">add</span>(<span class=\"num\">3</span>, <span class=\"num\">4</span>)         &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"fn\">add</span>(<span class=\"num\">1.5</span>, <span class=\"num\">2.25</span>)    &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"fn\">only_ints</span>(<span class=\"num\">21</span>)     &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"cm\">// only_ints(3.14);  // ERROR: 'double' does not satisfy 'integral'</span>\n\n    <span class=\"ty\">std::vector</span>&lt;<span class=\"ty\">int</span>&gt; v = {<span class=\"num\">10</span>, <span class=\"num\">20</span>, <span class=\"num\">30</span>};\n    <span class=\"fn\">print_container</span>(v);\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>7\n3.75\n42\n10 20 30</code></pre></div></div><p class=\"l-text\"><strong>Built-in standard concepts</strong> (header <code>&lt;concepts&gt;</code>): <code>std::integral</code>, <code>std::floating_point</code>, <code>std::signed_integral</code>, <code>std::same_as&lt;T,U&gt;</code>, <code>std::convertible_to&lt;From,To&gt;</code>, <code>std::derived_from&lt;Derived,Base&gt;</code>, <code>std::invocable&lt;F,Args...&gt;</code>, <code>std::equality_comparable</code>, <code>std::totally_ordered</code>. Combine them with <code>&amp;&amp;</code> and <code>||</code> right in the requires clause.</p><h3 class=\"l-h3\" style=\"margin-top:2.2rem\">STL Container Complexity — Pick the Right Tool</h3><p class=\"l-text\">When you choose a container, you are choosing a set of performance trade-offs. This table summarises the operations that matter most:</p><div class=\"calc-table-wrap\" style=\"overflow-x:auto;margin:1.2rem 0\"><table class=\"calc-table\" style=\"width:100%;border-collapse:collapse;font-size:0.92rem;line-height:1.5\"><thead><tr style=\"background:rgba(200,169,110,0.10);border-bottom:2px solid rgba(200,169,110,0.35)\"><th style=\"text-align:left;padding:0.65rem 0.8rem\">Container</th><th style=\"text-align:left;padding:0.65rem 0.8rem\">Lookup</th><th style=\"text-align:left;padding:0.65rem 0.8rem\">Insert</th><th style=\"text-align:left;padding:0.65rem 0.8rem\">Erase</th><th style=\"text-align:left;padding:0.65rem 0.8rem\">Random access</th><th style=\"text-align:left;padding:0.65rem 0.8rem\">Ordered?</th><th style=\"text-align:left;padding:0.65rem 0.8rem\">Memory</th></tr></thead><tbody><tr style=\"border-bottom:1px solid rgba(235,230,220,0.08)\"><td style=\"padding:0.55rem 0.8rem\"><code>vector</code></td><td style=\"padding:0.55rem 0.8rem\">O(n) linear / O(log n) if sorted</td><td style=\"padding:0.55rem 0.8rem\">O(1) amortized at end, O(n) elsewhere</td><td style=\"padding:0.55rem 0.8rem\">O(1) at end, O(n) elsewhere</td><td style=\"padding:0.55rem 0.8rem\"><strong>O(1)</strong></td><td style=\"padding:0.55rem 0.8rem\">insertion order</td><td style=\"padding:0.55rem 0.8rem\">contiguous, best cache</td></tr><tr style=\"border-bottom:1px solid rgba(235,230,220,0.08)\"><td style=\"padding:0.55rem 0.8rem\"><code>list</code></td><td style=\"padding:0.55rem 0.8rem\">O(n)</td><td style=\"padding:0.55rem 0.8rem\"><strong>O(1)</strong> with iterator</td><td style=\"padding:0.55rem 0.8rem\"><strong>O(1)</strong> with iterator</td><td style=\"padding:0.55rem 0.8rem\">O(n)</td><td style=\"padding:0.55rem 0.8rem\">insertion order</td><td style=\"padding:0.55rem 0.8rem\">nodes, poor cache</td></tr><tr style=\"border-bottom:1px solid rgba(235,230,220,0.08)\"><td style=\"padding:0.55rem 0.8rem\"><code>deque</code></td><td style=\"padding:0.55rem 0.8rem\">O(n)</td><td style=\"padding:0.55rem 0.8rem\">O(1) at both ends, O(n) middle</td><td style=\"padding:0.55rem 0.8rem\">O(1) at both ends</td><td style=\"padding:0.55rem 0.8rem\">O(1)</td><td style=\"padding:0.55rem 0.8rem\">insertion order</td><td style=\"padding:0.55rem 0.8rem\">chunked array</td></tr><tr style=\"border-bottom:1px solid rgba(235,230,220,0.08)\"><td style=\"padding:0.55rem 0.8rem\"><code>map</code> / <code>set</code></td><td style=\"padding:0.55rem 0.8rem\"><strong>O(log n)</strong></td><td style=\"padding:0.55rem 0.8rem\">O(log n)</td><td style=\"padding:0.55rem 0.8rem\">O(log n)</td><td style=\"padding:0.55rem 0.8rem\">—</td><td style=\"padding:0.55rem 0.8rem\"><strong>yes</strong> (red-black tree)</td><td style=\"padding:0.55rem 0.8rem\">tree nodes</td></tr><tr style=\"border-bottom:1px solid rgba(235,230,220,0.08)\"><td style=\"padding:0.55rem 0.8rem\"><code>unordered_map</code> / <code>unordered_set</code></td><td style=\"padding:0.55rem 0.8rem\"><strong>O(1)</strong> avg, O(n) worst</td><td style=\"padding:0.55rem 0.8rem\">O(1) avg, O(n) worst</td><td style=\"padding:0.55rem 0.8rem\">O(1) avg</td><td style=\"padding:0.55rem 0.8rem\">—</td><td style=\"padding:0.55rem 0.8rem\">no (hash)</td><td style=\"padding:0.55rem 0.8rem\">buckets + nodes</td></tr><tr><td style=\"padding:0.55rem 0.8rem\"><code>array&lt;T,N&gt;</code></td><td style=\"padding:0.55rem 0.8rem\">O(n) / O(log n) sorted</td><td style=\"padding:0.55rem 0.8rem\">— (fixed size)</td><td style=\"padding:0.55rem 0.8rem\">— (fixed size)</td><td style=\"padding:0.55rem 0.8rem\"><strong>O(1)</strong></td><td style=\"padding:0.55rem 0.8rem\">insertion order</td><td style=\"padding:0.55rem 0.8rem\">contiguous, stack</td></tr></tbody></table></div><div class=\"l-note\"><strong>Quick decision guide:</strong> Need a sequence? <code>vector</code>. Need fast key lookup with order? <code>map</code>. Need fastest possible key lookup and don't care about order? <code>unordered_map</code>. Need queue-like push/pop at both ends? <code>deque</code>. Almost never reach for <code>list</code> — its O(1) splice and stable iterators are useful, but the cache miss cost usually outweighs the algorithmic win.</div>",
tr: "<p class=\"l-text\">Şablonlar, C++'ın <strong>genel programlama</strong> mekanizmasıdır — herhangi bir türle çalışan kod yazmak. Çözdükleri problem basittir: şablonlar olmadan, aynı fonksiyonun her tür için ayrı versiyonlarını yazmak zorunda kalırdınız. Bir <code>max</code> fonksiyonu mu gerekiyor? <code>int</code> için bir tane, <code>double</code> için bir tane, <code>string</code> için bir tane yazın... Şablonlar bir kez yazmanızı sağlar.</p><div class=\"lesson-outcomes\" style=\"background:rgba(200,169,110,0.06);border-left:3px solid #c8a96e;padding:1rem 1.2rem;margin:1.5rem 0;border-radius:0 8px 8px 0\"><div style=\"font-size:0.78rem;font-weight:700;letter-spacing:0.08em;color:#c8a96e;margin-bottom:0.6rem\">📍 BU DERSTE ÖĞRENECEKSİN</div><ul style=\"margin:0;padding-left:1.3rem;line-height:1.65;font-size:0.93rem;color:rgba(235,230,220,0.92)\"><li>Herhangi uyumlu türle çalışan fonksiyon ve sınıf template'i tanımla</li><li>Performans-kritik türler için gerektiğinde template'leri özelleştir</li><li>Esnek API'lar için template parameter pack ve variadic template kullan</li><li>Net hatalarla template parametrelerini kısıtlamak için concept'leri (C++20) uygula</li><li>Template'lerle generic bir Stack veya Queue veri yapısı inşa et</li></ul></div><div class=\"l-highlight\"><strong>Şablonlar olmadan DRY problemi:</strong> <code>int max_int(int a, int b)</code>, <code>double max_double(double a, double b)</code>, <code>string max_string(string a, string b)</code> yazmayı düşünün — hepsi aynı mantıkla. Şimdi bir hata düzeltmesi düşünün: üçünü de güncellemek zorundasınız. Şablonlar bu tekrarı tamamen ortadan kaldırır.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> templates.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"cm\">// Fonksiyon şablonu: &gt; destekleyen HER türle çalışır</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n<span class=\"ty\">T</span> <span class=\"fn\">max_val</span>(<span class=\"ty\">T</span> a, <span class=\"ty\">T</span> b) {\n    <span class=\"kw\">return</span> (a &gt; b) ? a : b;\n}\n\n<span class=\"cm\">// Birden fazla tür parametreli şablon</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>, <span class=\"kw\">typename</span> <span class=\"ty\">U</span>&gt;\n<span class=\"ty\">void</span> <span class=\"fn\">print_pair</span>(<span class=\"kw\">const</span> <span class=\"ty\">T</span>&amp; first, <span class=\"kw\">const</span> <span class=\"ty\">U</span>&amp; second) {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"(\"</span> &lt;&lt; first &lt;&lt; <span class=\"str\">\", \"</span> &lt;&lt; second &lt;&lt; <span class=\"str\">\")\\n\"</span>;\n}\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"cm\">// Derleyici int, double, string versiyonlarını otomatik üretir</span>\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"max(3, 7) = \"</span> &lt;&lt; <span class=\"fn\">max_val</span>(<span class=\"num\">3</span>, <span class=\"num\">7</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"max(3.14, 2.72) = \"</span> &lt;&lt; <span class=\"fn\">max_val</span>(<span class=\"num\">3.14</span>, <span class=\"num\">2.72</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"max(\\\"apple\\\", \\\"banana\\\") = \"</span>\n              &lt;&lt; <span class=\"fn\">max_val</span>(<span class=\"ty\">std::string</span>(<span class=\"str\">\"apple\"</span>), <span class=\"ty\">std::string</span>(<span class=\"str\">\"banana\"</span>)) &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"fn\">print_pair</span>(<span class=\"str\">\"age\"</span>, <span class=\"num\">25</span>);\n    <span class=\"fn\">print_pair</span>(<span class=\"num\">3.14</span>, <span class=\"str\">\"pi\"</span>);\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>max(3, 7) = 7\nmax(3.14, 2.72) = 3.14\nmax(\"apple\", \"banana\") = banana\n(age, 25)\n(3.14, pi)</code></pre></div></div><p class=\"l-text\"><strong>Şablon örnekleme nasıl çalışır:</strong> Şablonlar gerçekte kullanılana kadar koda derlenmez. <code>max_val(3, 7)</code> çağırdığınızda, derleyici <code>T = int</code> görür ve somut bir <code>int max_val(int, int)</code> fonksiyonu üretir. Buna <strong>örnekleme</strong> denir. Derleyici kullandığınız her tür için fonksiyonun yeni bir kopyasını oluşturur. Bu yüzden şablonlar genellikle başlık dosyalarında tanımlanır — derleyicinin örneklemek için tam tanımı görmesi gerekir.</p><p class=\"l-text\"><strong>Sınıf şablonları</strong> — tüm sınıfları da şablonlayabilirsiniz. Basit bir Stack oluşturalım:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> stack_template.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;vector&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;stdexcept&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n<span class=\"kw\">class</span> <span class=\"ty\">Stack</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"ty\">std::vector</span>&lt;<span class=\"ty\">T</span>&gt; data_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">void</span> <span class=\"fn\">push</span>(<span class=\"kw\">const</span> <span class=\"ty\">T</span>&amp; val) { data_.<span class=\"fn\">push_back</span>(val); }\n\n    <span class=\"ty\">T</span> <span class=\"fn\">pop</span>() {\n        <span class=\"kw\">if</span> (data_.<span class=\"fn\">empty</span>()) <span class=\"kw\">throw</span> <span class=\"ty\">std::runtime_error</span>(<span class=\"str\">\"Stack underflow\"</span>);\n        <span class=\"ty\">T</span> val = data_.<span class=\"fn\">back</span>();\n        data_.<span class=\"fn\">pop_back</span>();\n        <span class=\"kw\">return</span> val;\n    }\n\n    <span class=\"kw\">const</span> <span class=\"ty\">T</span>&amp; <span class=\"fn\">top</span>() <span class=\"kw\">const</span> {\n        <span class=\"kw\">if</span> (data_.<span class=\"fn\">empty</span>()) <span class=\"kw\">throw</span> <span class=\"ty\">std::runtime_error</span>(<span class=\"str\">\"Stack empty\"</span>);\n        <span class=\"kw\">return</span> data_.<span class=\"fn\">back</span>();\n    }\n\n    <span class=\"ty\">bool</span> <span class=\"fn\">empty</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> data_.<span class=\"fn\">empty</span>(); }\n    <span class=\"ty\">size_t</span> <span class=\"fn\">size</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> data_.<span class=\"fn\">size</span>(); }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"ty\">Stack</span>&lt;<span class=\"ty\">int</span>&gt; nums;\n    nums.<span class=\"fn\">push</span>(<span class=\"num\">10</span>);\n    nums.<span class=\"fn\">push</span>(<span class=\"num\">20</span>);\n    nums.<span class=\"fn\">push</span>(<span class=\"num\">30</span>);\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Int stack: \"</span>;\n    <span class=\"kw\">while</span> (!nums.<span class=\"fn\">empty</span>()) {\n        <span class=\"fn\">std::cout</span> &lt;&lt; nums.<span class=\"fn\">pop</span>() &lt;&lt; <span class=\"str\">\" \"</span>;\n    }\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"ty\">Stack</span>&lt;<span class=\"ty\">std::string</span>&gt; words;\n    words.<span class=\"fn\">push</span>(<span class=\"str\">\"Hello\"</span>);\n    words.<span class=\"fn\">push</span>(<span class=\"str\">\"World\"</span>);\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"String stack top: \"</span> &lt;&lt; words.<span class=\"fn\">top</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Int stack: 30 20 10\nString stack top: World</code></pre></div></div><p class=\"l-text\"><strong>STL Konteynerleri</strong> — Standart Şablon Kütüphanesi üretim kalitesinde konteynerler sağlar. Doğrusunu seçmek performans için önemlidir:</p><ul class=\"l-list\"><li><strong><code>vector</code></strong> — dinamik dizi. Varsayılan konteyneriniz. O(1) rastgele erişim, O(1) amortize push_back. Belirli bir nedeniniz olmadıkça bunu kullanın.</li><li><strong><code>list</code></strong> — çift bağlı liste. O(1) herhangi bir yere ekleme/çıkarma (yineleyiciniz varsa), ama O(n) rastgele erişim ve düşük önbellek yerelliyi.</li><li><strong><code>map</code></strong> — sıralı anahtar-değer çiftleri (kırmızı-siyah ağaç). O(log n) arama/ekleme. Anahtarlar sıralı kalır.</li><li><strong><code>unordered_map</code></strong> — hash tablosu. Ortalama O(1) arama/ekleme. Çoğu durumda map'ten hızlıdır, ama sıralama yoktur.</li><li><strong><code>set</code></strong> — sıralı benzersiz elemanlar. Değersiz map gibi.</li><li><strong><code>stack</code> / <code>queue</code></strong> — LIFO/FIFO adapterleri. Deque üzerine kısıtlı arayüzler.</li></ul><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> stl_containers.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;vector&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;map&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;set&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;algorithm&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;numeric&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"cm\">// === VECTOR ===</span>\n    <span class=\"ty\">std::vector</span>&lt;<span class=\"ty\">int</span>&gt; nums = {<span class=\"num\">5</span>, <span class=\"num\">2</span>, <span class=\"num\">8</span>, <span class=\"num\">1</span>, <span class=\"num\">9</span>, <span class=\"num\">3</span>};\n    <span class=\"fn\">std::sort</span>(nums.<span class=\"fn\">begin</span>(), nums.<span class=\"fn\">end</span>());\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Sorted: \"</span>;\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> n : nums) <span class=\"fn\">std::cout</span> &lt;&lt; n &lt;&lt; <span class=\"str\">\" \"</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"ty\">int</span> sum = <span class=\"fn\">std::accumulate</span>(nums.<span class=\"fn\">begin</span>(), nums.<span class=\"fn\">end</span>(), <span class=\"num\">0</span>);\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Sum: \"</span> &lt;&lt; sum &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"kw\">auto</span> it = <span class=\"fn\">std::find</span>(nums.<span class=\"fn\">begin</span>(), nums.<span class=\"fn\">end</span>(), <span class=\"num\">8</span>);\n    <span class=\"kw\">if</span> (it != nums.<span class=\"fn\">end</span>()) {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Found 8 at index \"</span> &lt;&lt; (it - nums.<span class=\"fn\">begin</span>()) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"cm\">// === MAP ===</span>\n    <span class=\"ty\">std::map</span>&lt;<span class=\"ty\">std::string</span>, <span class=\"ty\">int</span>&gt; ages;\n    ages[<span class=\"str\">\"Begüm\"</span>] = <span class=\"num\">30</span>;\n    ages[<span class=\"str\">\"Mikail\"</span>] = <span class=\"num\">25</span>;\n    ages[<span class=\"str\">\"Defne\"</span>] = <span class=\"num\">35</span>;\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"\\nMap (sorted by key):\\n\"</span>;\n    <span class=\"kw\">for</span> (<span class=\"kw\">const</span> <span class=\"kw\">auto</span>&amp; [name, age] : ages) {  <span class=\"cm\">// yapılandırılmış bağlama (C++17)</span>\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  \"</span> &lt;&lt; name &lt;&lt; <span class=\"str\">\": \"</span> &lt;&lt; age &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"cm\">// === SET ===</span>\n    <span class=\"ty\">std::set</span>&lt;<span class=\"ty\">int</span>&gt; unique = {<span class=\"num\">3</span>, <span class=\"num\">1</span>, <span class=\"num\">4</span>, <span class=\"num\">1</span>, <span class=\"num\">5</span>, <span class=\"num\">9</span>, <span class=\"num\">2</span>, <span class=\"num\">6</span>, <span class=\"num\">5</span>};\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"\\nSet (unique, sorted): \"</span>;\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> n : unique) <span class=\"fn\">std::cout</span> &lt;&lt; n &lt;&lt; <span class=\"str\">\" \"</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Sorted: 1 2 3 5 8 9\nSum: 28\nFound 8 at index 4\n\nMap (sorted by key):\n  Begüm: 30\n  Mikail: 25\n  Defne: 35\n\nSet (unique, sorted): 1 2 3 4 5 6 9</code></pre></div></div><p class=\"l-text\"><strong>STL Algoritmaları</strong> — <code>&lt;algorithm&gt;</code> başlığı, yineleyiciler aracılığıyla herhangi bir konteynerle çalışan düzinelerce hazır algoritma sağlar: <code>sort</code>, <code>find</code>, <code>count</code>, <code>transform</code>, <code>accumulate</code>, <code>remove_if</code>, <code>any_of</code>, <code>all_of</code> ve daha birçoğu. \"Ne yapılacağını\" \"hangi konteynerde yapılacağından\" ayırırlar — aynı <code>sort</code> vector, dizi ve deque üzerinde çalışır.</p><div class=\"l-note\"><strong>İpucu:</strong> Konteyner seçerken, varsayılan olarak <code>std::vector</code> kullanın. En iyi önbellek performansına sahiptir (bitkişik bellek) ve küçük koleksiyonlar için (birkaç yüz elemana kadar), ikili aramalı sıralı bir vector önbellek yerelliyi nedeniyle genellikle <code>map</code>'ten daha hızlıdır.</div><h3 class=\"l-h3\" style=\"margin-top:2.2rem\">Şablon Uzmanlaştırma — Tam ve Kısmi</h3><p class=\"l-text\">Bazen generic şablon <em>neredeyse</em> doğrudur, ama belirli bir türün özel davranışa ihtiyacı vardır — belki performans için, belki de generic algoritma o tür için anlamsız olduğu için. <strong>Şablon uzmanlaştırma</strong> belirli bir tür için tamamen ayrı bir uygulama yazmanıza (tam uzmanlaştırma) ya da \"tüm pointer'lar\" gibi bir tür ailesi için yazmanıza (kısmi uzmanlaştırma) izin verir. Klasik gerçek hayat örneği <code>std::vector&lt;bool&gt;</code>: her boolean'ı bir byte yerine, byte başına 8 bool olacak şekilde paketleyen özel bir uzmanlaştırmadır.</p><div class=\"calc-cards\"><div class=\"calc-card\"><div class=\"cc-title\">Tam Uzmanlaştırma</div><div class=\"cc-body\">Tek bir tam tür için şablonu baştan sona değiştirir: <code>template&lt;&gt; class MyClass&lt;int&gt; { ... };</code>. Bir türün tamamen farklı bir uygulamaya ihtiyacı olduğunda kullanılır.</div></div><div class=\"calc-card\"><div class=\"cc-title\">Kısmi Uzmanlaştırma</div><div class=\"cc-body\">Şablonu bir tür ailesine kısıtlar — sadece sınıf şablonlarında geçerli: <code>template&lt;typename T&gt; class MyClass&lt;T*&gt; { ... };</code>. Yukarıdaki örnek her pointer türüyle eşleşir.</div></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> specialization.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"cm\">// Birincil şablon — her T için geçerli</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n<span class=\"kw\">struct</span> <span class=\"ty\">TypeInfo</span> {\n    <span class=\"kw\">static</span> <span class=\"ty\">std::string</span> <span class=\"fn\">name</span>() { <span class=\"kw\">return</span> <span class=\"str\">\"unknown\"</span>; }\n    <span class=\"kw\">static</span> <span class=\"kw\">constexpr</span> <span class=\"ty\">bool</span> is_pointer = <span class=\"kw\">false</span>;\n};\n\n<span class=\"cm\">// int için tam uzmanlaştırma</span>\n<span class=\"kw\">template</span>&lt;&gt;\n<span class=\"kw\">struct</span> <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">int</span>&gt; {\n    <span class=\"kw\">static</span> <span class=\"ty\">std::string</span> <span class=\"fn\">name</span>() { <span class=\"kw\">return</span> <span class=\"str\">\"int\"</span>; }\n    <span class=\"kw\">static</span> <span class=\"kw\">constexpr</span> <span class=\"ty\">bool</span> is_pointer = <span class=\"kw\">false</span>;\n};\n\n<span class=\"cm\">// double için tam uzmanlaştırma</span>\n<span class=\"kw\">template</span>&lt;&gt;\n<span class=\"kw\">struct</span> <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">double</span>&gt; {\n    <span class=\"kw\">static</span> <span class=\"ty\">std::string</span> <span class=\"fn\">name</span>() { <span class=\"kw\">return</span> <span class=\"str\">\"double\"</span>; }\n    <span class=\"kw\">static</span> <span class=\"kw\">constexpr</span> <span class=\"ty\">bool</span> is_pointer = <span class=\"kw\">false</span>;\n};\n\n<span class=\"cm\">// KISMİ uzmanlaştırma: T* — her pointer türü</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n<span class=\"kw\">struct</span> <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">T</span>*&gt; {\n    <span class=\"kw\">static</span> <span class=\"ty\">std::string</span> <span class=\"fn\">name</span>() { <span class=\"kw\">return</span> <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">T</span>&gt;::<span class=\"fn\">name</span>() + <span class=\"str\">\"*\"</span>; }\n    <span class=\"kw\">static</span> <span class=\"kw\">constexpr</span> <span class=\"ty\">bool</span> is_pointer = <span class=\"kw\">true</span>;\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">int</span>&gt;::<span class=\"fn\">name</span>()       &lt;&lt; <span class=\"str\">\" ptr=\"</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">int</span>&gt;::is_pointer       &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">double</span>&gt;::<span class=\"fn\">name</span>()    &lt;&lt; <span class=\"str\">\" ptr=\"</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">double</span>&gt;::is_pointer    &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">int</span>*&gt;::<span class=\"fn\">name</span>()      &lt;&lt; <span class=\"str\">\" ptr=\"</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">int</span>*&gt;::is_pointer      &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">double</span>*&gt;::<span class=\"fn\">name</span>()   &lt;&lt; <span class=\"str\">\" ptr=\"</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">double</span>*&gt;::is_pointer   &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"ty\">TypeInfo</span>&lt;<span class=\"ty\">char</span>&gt;::<span class=\"fn\">name</span>()      &lt;&lt; <span class=\"str\">'\\n'</span>;  <span class=\"cm\">// birincile düşer</span>\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>int ptr=0\ndouble ptr=0\nint* ptr=1\ndouble* ptr=1\nunknown</code></pre></div></div><p class=\"l-text\"><code>TypeInfo&lt;char&gt;</code>'ın eşleşen bir uzmanlaştırma olmadığı için <em>birincil</em> şablona (\"unknown\") düştüğüne dikkat edin. Derleyici mevcut en spesifik eşleşmeyi seçer — önce tam uzmanlaştırmalar, sonra kısmi, sonra birincil. Standart kütüphanenin <code>std::is_pointer</code> ve <code>std::remove_pointer</code> gibi trait'leri tam olarak böyle uygular.</p><h3 class=\"l-h3\" style=\"margin-top:2.2rem\">Değişken Sayılı Şablonlar ve Parametre Paketleri</h3><p class=\"l-text\">C++11'den önce şablonlar sabit sayıda tür parametresi kabul ederdi. <strong>Değişken sayılı (variadic) şablonlar</strong> bunu değiştirdi: tek bir şablon artık istediğiniz kadar, istediğiniz türde argüman alabilir. <code>template&lt;typename... Args&gt;</code> sözdizimi bir <em>parametre paketi</em> tanımlar — <code>Args</code> tek bir tür değil, bir tür listesidir. Paketi fonksiyon imzalarında <code>Args...</code>, çağrı ifadelerinde <code>args...</code> ile açarsınız. <code>std::tuple</code>, <code>std::make_shared</code>, <code>std::vector::emplace_back</code> ve tip-güvenli <code>printf</code> benzeri formatlayıcılar tam olarak böyle kurulur.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> variadic.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"cm\">// --- Yöntem 1: özyinelemeli variadic (C++17 öncesi) ---</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n<span class=\"ty\">T</span> <span class=\"fn\">sum_rec</span>(<span class=\"ty\">T</span> v) { <span class=\"kw\">return</span> v; }                <span class=\"cm\">// taban durumu</span>\n\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>, <span class=\"kw\">typename</span>... <span class=\"ty\">Rest</span>&gt;\n<span class=\"ty\">T</span> <span class=\"fn\">sum_rec</span>(<span class=\"ty\">T</span> first, <span class=\"ty\">Rest</span>... rest) {\n    <span class=\"kw\">return</span> first + <span class=\"fn\">sum_rec</span>(rest...);     <span class=\"cm\">// birini ayır, özyinele</span>\n}\n\n<span class=\"cm\">// --- Yöntem 2: fold ifadesi (C++17, çok daha sade) ---</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span>... <span class=\"ty\">Args</span>&gt;\n<span class=\"kw\">auto</span> <span class=\"fn\">sum_fold</span>(<span class=\"ty\">Args</span>... args) {\n    <span class=\"kw\">return</span> (args + ...);                  <span class=\"cm\">// tekli sağ fold: a1+(a2+(a3+a4))</span>\n}\n\n<span class=\"cm\">// Virgül operatörü üzerinden fold ile değişken sayılı print</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span>... <span class=\"ty\">Args</span>&gt;\n<span class=\"ty\">void</span> <span class=\"fn\">print_all</span>(<span class=\"kw\">const</span> <span class=\"ty\">Args</span>&amp;... args) {\n    ((<span class=\"fn\">std::cout</span> &lt;&lt; args &lt;&lt; <span class=\"str\">\" \"</span>), ...);\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n}\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"sum_rec(1,2,3,4,5)  = \"</span> &lt;&lt; <span class=\"fn\">sum_rec</span>(<span class=\"num\">1</span>,<span class=\"num\">2</span>,<span class=\"num\">3</span>,<span class=\"num\">4</span>,<span class=\"num\">5</span>)  &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"sum_fold(1,2,3,4,5) = \"</span> &lt;&lt; <span class=\"fn\">sum_fold</span>(<span class=\"num\">1</span>,<span class=\"num\">2</span>,<span class=\"num\">3</span>,<span class=\"num\">4</span>,<span class=\"num\">5</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"sum_fold(1.5, 2.5)  = \"</span> &lt;&lt; <span class=\"fn\">sum_fold</span>(<span class=\"num\">1.5</span>, <span class=\"num\">2.5</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"fn\">print_all</span>(<span class=\"str\">\"id=\"</span>, <span class=\"num\">42</span>, <span class=\"str\">\"name=\"</span>, <span class=\"ty\">std::string</span>(<span class=\"str\">\"Mikail\"</span>), <span class=\"str\">\"pi=\"</span>, <span class=\"num\">3.14</span>);\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>sum_rec(1,2,3,4,5)  = 15\nsum_fold(1,2,3,4,5) = 15\nsum_fold(1.5, 2.5)  = 4\nid= 42 name= Mikail pi= 3.14</code></pre></div></div><div class=\"l-highlight\"><strong>Fold ifadesi özeti (C++17):</strong> <code>(pack op ...)</code> tekli sağ fold, <code>(... op pack)</code> tekli sol fold, <code>(pack op ... op init)</code> başlangıç değerli ikili sağ fold. Kullanışlı operatörler: <code>+</code>, <code>*</code>, <code>&amp;&amp;</code>, <code>||</code> ve paket üzerinde yan etkili döngü için virgül operatörü <code>,</code>.</div><p class=\"l-text\"><strong>Standart kütüphane bunu nerede kullanır:</strong> <code>std::make_shared&lt;T&gt;(args...)</code> herhangi bir kurucu argümanını <code>T</code>'ye parametre paketi ve <code>std::forward&lt;Args&gt;(args)...</code> ile (mükemmel iletme) aktarır. <code>std::tuple&lt;Ts...&gt;</code> heterojen bir liste tutar. <code>std::vector::emplace_back(args...)</code> elemanı iletilen paketten yerinde kurar — sıfır kopya, sıfır taşıma.</p><h3 class=\"l-h3\" style=\"margin-top:2.2rem\">C++20 Kavramları (Concepts) — İngilizce Gibi Okunan Kısıtlar</h3><p class=\"l-text\">C++20'den önce bir şablonu kısıtlamanın tek yolu <strong>SFINAE</strong> (Substitution Failure Is Not An Error) idi — sonucu, içinde <code>std::enable_if&lt;std::is_integral_v&lt;T&gt; &amp;&amp; ...&gt;::type</code> dolu 200 satırlık hata mesajları olurdu. <strong>Kavramlar (concepts)</strong> bunun yerine adlandırılmış, okunabilir kısıtlar getirir. Bir kavram, türler üzerinde derleme-zamanı yüklemidir; <code>requires</code> ifadesi onu şablona bağlar.</p><div class=\"calc-cards\"><div class=\"calc-card\"><div class=\"cc-title\">Eski SFINAE</div><div class=\"cc-body\"><code>template&lt;typename T, std::enable_if_t&lt;std::is_integral_v&lt;T&gt;, int&gt; = 0&gt;</code> — çalışır, ama hatalar bir duvar ve niyet gizlidir.</div></div><div class=\"calc-card\"><div class=\"cc-title\">Yeni Kavramlar</div><div class=\"cc-body\"><code>template&lt;std::integral T&gt;</code> ya da <code>template&lt;typename T&gt; requires std::integral&lt;T&gt;</code> — aynı kısıt, tek satır, hatalar \"T integral'i karşılamıyor\" der.</div></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> concepts.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;concepts&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;vector&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"cm\">// Kendi kavramını tanımla: \"a + b'yi destekleyen tür\"</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n<span class=\"kw\">concept</span> <span class=\"ty\">Addable</span> = <span class=\"kw\">requires</span>(<span class=\"ty\">T</span> a, <span class=\"ty\">T</span> b) {\n    { a + b } -&gt; <span class=\"ty\">std::convertible_to</span>&lt;<span class=\"ty\">T</span>&gt;;\n};\n\n<span class=\"cm\">// Kavramı doğrudan şablon parametresinde kullan</span>\n<span class=\"kw\">template</span>&lt;<span class=\"ty\">Addable</span> <span class=\"ty\">T</span>&gt;\n<span class=\"ty\">T</span> <span class=\"fn\">add</span>(<span class=\"ty\">T</span> a, <span class=\"ty\">T</span> b) { <span class=\"kw\">return</span> a + b; }\n\n<span class=\"cm\">// Standart kavramı requires ifadesiyle kullan</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">T</span>&gt;\n    <span class=\"kw\">requires</span> <span class=\"ty\">std::integral</span>&lt;<span class=\"ty\">T</span>&gt;\n<span class=\"ty\">T</span> <span class=\"fn\">only_ints</span>(<span class=\"ty\">T</span> x) { <span class=\"kw\">return</span> x * <span class=\"num\">2</span>; }\n\n<span class=\"cm\">// Daha ilginç bir kavram: bir Container'ın begin(), end() ve value_type'ı vardır</span>\n<span class=\"kw\">template</span>&lt;<span class=\"kw\">typename</span> <span class=\"ty\">C</span>&gt;\n<span class=\"kw\">concept</span> <span class=\"ty\">Container</span> = <span class=\"kw\">requires</span>(<span class=\"ty\">C</span> c) {\n    c.<span class=\"fn\">begin</span>();\n    c.<span class=\"fn\">end</span>();\n    <span class=\"kw\">typename</span> <span class=\"ty\">C</span>::value_type;\n};\n\n<span class=\"kw\">template</span>&lt;<span class=\"ty\">Container</span> <span class=\"ty\">C</span>&gt;\n<span class=\"ty\">void</span> <span class=\"fn\">print_container</span>(<span class=\"kw\">const</span> <span class=\"ty\">C</span>&amp; c) {\n    <span class=\"kw\">for</span> (<span class=\"kw\">const</span> <span class=\"kw\">auto</span>&amp; x : c) <span class=\"fn\">std::cout</span> &lt;&lt; x &lt;&lt; <span class=\"str\">\" \"</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n}\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"fn\">add</span>(<span class=\"num\">3</span>, <span class=\"num\">4</span>)         &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"fn\">add</span>(<span class=\"num\">1.5</span>, <span class=\"num\">2.25</span>)    &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"fn\">only_ints</span>(<span class=\"num\">21</span>)     &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"cm\">// only_ints(3.14);  // HATA: 'double', 'integral' kavramını karşılamıyor</span>\n\n    <span class=\"ty\">std::vector</span>&lt;<span class=\"ty\">int</span>&gt; v = {<span class=\"num\">10</span>, <span class=\"num\">20</span>, <span class=\"num\">30</span>};\n    <span class=\"fn\">print_container</span>(v);\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>7\n3.75\n42\n10 20 30</code></pre></div></div><p class=\"l-text\"><strong>Yerleşik standart kavramlar</strong> (<code>&lt;concepts&gt;</code> başlığı): <code>std::integral</code>, <code>std::floating_point</code>, <code>std::signed_integral</code>, <code>std::same_as&lt;T,U&gt;</code>, <code>std::convertible_to&lt;From,To&gt;</code>, <code>std::derived_from&lt;Derived,Base&gt;</code>, <code>std::invocable&lt;F,Args...&gt;</code>, <code>std::equality_comparable</code>, <code>std::totally_ordered</code>. <code>requires</code> ifadesinin içinde <code>&amp;&amp;</code> ve <code>||</code> ile birleştirilebilirler.</p><h3 class=\"l-h3\" style=\"margin-top:2.2rem\">STL Konteyner Karmaşıklığı — Doğru Aracı Seç</h3><p class=\"l-text\">Bir konteyner seçtiğinizde aslında bir performans ödün setine karar veriyorsunuz. Bu tablo en önemli operasyonları özetler:</p><div class=\"calc-table-wrap\" style=\"overflow-x:auto;margin:1.2rem 0\"><table class=\"calc-table\" style=\"width:100%;border-collapse:collapse;font-size:0.92rem;line-height:1.5\"><thead><tr style=\"background:rgba(200,169,110,0.10);border-bottom:2px solid rgba(200,169,110,0.35)\"><th style=\"text-align:left;padding:0.65rem 0.8rem\">Konteyner</th><th style=\"text-align:left;padding:0.65rem 0.8rem\">Arama</th><th style=\"text-align:left;padding:0.65rem 0.8rem\">Ekleme</th><th style=\"text-align:left;padding:0.65rem 0.8rem\">Silme</th><th style=\"text-align:left;padding:0.65rem 0.8rem\">Rastgele erişim</th><th style=\"text-align:left;padding:0.65rem 0.8rem\">Sıralı mı?</th><th style=\"text-align:left;padding:0.65rem 0.8rem\">Bellek</th></tr></thead><tbody><tr style=\"border-bottom:1px solid rgba(235,230,220,0.08)\"><td style=\"padding:0.55rem 0.8rem\"><code>vector</code></td><td style=\"padding:0.55rem 0.8rem\">O(n) doğrusal / sıralıysa O(log n)</td><td style=\"padding:0.55rem 0.8rem\">Sona O(1) amortize, başka yere O(n)</td><td style=\"padding:0.55rem 0.8rem\">Sondan O(1), başka yerden O(n)</td><td style=\"padding:0.55rem 0.8rem\"><strong>O(1)</strong></td><td style=\"padding:0.55rem 0.8rem\">ekleme sırası</td><td style=\"padding:0.55rem 0.8rem\">bitişik, en iyi önbellek</td></tr><tr style=\"border-bottom:1px solid rgba(235,230,220,0.08)\"><td style=\"padding:0.55rem 0.8rem\"><code>list</code></td><td style=\"padding:0.55rem 0.8rem\">O(n)</td><td style=\"padding:0.55rem 0.8rem\">İteratörle <strong>O(1)</strong></td><td style=\"padding:0.55rem 0.8rem\">İteratörle <strong>O(1)</strong></td><td style=\"padding:0.55rem 0.8rem\">O(n)</td><td style=\"padding:0.55rem 0.8rem\">ekleme sırası</td><td style=\"padding:0.55rem 0.8rem\">düğümler, kötü önbellek</td></tr><tr style=\"border-bottom:1px solid rgba(235,230,220,0.08)\"><td style=\"padding:0.55rem 0.8rem\"><code>deque</code></td><td style=\"padding:0.55rem 0.8rem\">O(n)</td><td style=\"padding:0.55rem 0.8rem\">İki uçtan O(1), ortaya O(n)</td><td style=\"padding:0.55rem 0.8rem\">İki uçtan O(1)</td><td style=\"padding:0.55rem 0.8rem\">O(1)</td><td style=\"padding:0.55rem 0.8rem\">ekleme sırası</td><td style=\"padding:0.55rem 0.8rem\">parçalı dizi</td></tr><tr style=\"border-bottom:1px solid rgba(235,230,220,0.08)\"><td style=\"padding:0.55rem 0.8rem\"><code>map</code> / <code>set</code></td><td style=\"padding:0.55rem 0.8rem\"><strong>O(log n)</strong></td><td style=\"padding:0.55rem 0.8rem\">O(log n)</td><td style=\"padding:0.55rem 0.8rem\">O(log n)</td><td style=\"padding:0.55rem 0.8rem\">—</td><td style=\"padding:0.55rem 0.8rem\"><strong>evet</strong> (kırmızı-siyah ağaç)</td><td style=\"padding:0.55rem 0.8rem\">ağaç düğümleri</td></tr><tr style=\"border-bottom:1px solid rgba(235,230,220,0.08)\"><td style=\"padding:0.55rem 0.8rem\"><code>unordered_map</code> / <code>unordered_set</code></td><td style=\"padding:0.55rem 0.8rem\">Ortalama <strong>O(1)</strong>, en kötü O(n)</td><td style=\"padding:0.55rem 0.8rem\">Ortalama O(1), en kötü O(n)</td><td style=\"padding:0.55rem 0.8rem\">Ortalama O(1)</td><td style=\"padding:0.55rem 0.8rem\">—</td><td style=\"padding:0.55rem 0.8rem\">hayır (hash)</td><td style=\"padding:0.55rem 0.8rem\">bucket + düğüm</td></tr><tr><td style=\"padding:0.55rem 0.8rem\"><code>array&lt;T,N&gt;</code></td><td style=\"padding:0.55rem 0.8rem\">O(n) / sıralıysa O(log n)</td><td style=\"padding:0.55rem 0.8rem\">— (sabit boy)</td><td style=\"padding:0.55rem 0.8rem\">— (sabit boy)</td><td style=\"padding:0.55rem 0.8rem\"><strong>O(1)</strong></td><td style=\"padding:0.55rem 0.8rem\">ekleme sırası</td><td style=\"padding:0.55rem 0.8rem\">bitişik, yığıt</td></tr></tbody></table></div><div class=\"l-note\"><strong>Hızlı seçim rehberi:</strong> Bir dizi mi lazım? <code>vector</code>. Sıralı, hızlı anahtar araması mı? <code>map</code>. En hızlı anahtar araması ve sıra önemsiz mi? <code>unordered_map</code>. İki uçtan kuyruk gibi push/pop mu? <code>deque</code>. <code>list</code>'e neredeyse hiç başvurmayın — O(1) splice ve kararlı iteratörleri kullanışlı, ama önbellek kaçırma maliyeti genellikle algoritmik avantajdan büyüktür.</div>"
};
